		["Into the {zone:1418}"] = "Hacia {zone:1418}",
		["Lesser Rock Elementals"] = "Elementales de piedra inferiores",
		["North-east of Hammerfall the Drywhisker kobolds mine the gorge; the Kobolds at the mouth and the Diggers and Surveyors deeper in all drop the Motes of Myzrael."] = "Al noreste de Sentencia, los kobolds Mostacho Seco excavan la garganta; los kobolds de la entrada y los excavadores y topógrafos del fondo sueltan las Motas de Myzrael.",
		["Ride north; the outer circle stands in the middle of the highlands."] = "Cabalga al norte; el círculo exterior está en el centro de las tierras altas.",
		["Ride south-west to the goblins' cove on the southern coast. {npc:2766} keeps watch on the cliff above it."] = "Cabalga al suroeste hasta la cala de los goblins en la costa sur. {npc:2766} vigila desde el acantilado de encima.",
		["Rock Elementals"] = "Elementales de piedra",
		["Stonevault troggs"] = "Troggs Grutacanto",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202}."] = "Toma el zepelín de {zone:1454} en la torre del lado oeste de {object:3202}.",
		["The Greater Rock Elementals (42-44, well above you) wander the gulches in the south-west; the bracers drop about one kill in five. Pull one at a time and rest between fights, or leave them. Keep killing coyotes and buzzards you still need on the way."] = "Los Elementales de piedra mayores (42-44, muy por encima de ti) vagan por los barrancos del suroeste; los brazales caen más o menos en una de cada cinco muertes. Atráelos de uno en uno y descansa entre combates, o déjalos. Sigue matando por el camino los coyotes y águilas ratoneras que aún necesites.",
		["The Syndicate hold the walled manor and its farm in the north-west; their Highwaymen, Mercenaries and Pathstalkers carry the Bloodstone Amulets."] = "El Sindicato ocupa la mansión amurallada y su granja en el noroeste; sus salteadores, mercenarios y acechasendas llevan los Amuletos de Petrosangre.",
		["The Witherbark trolls hold the village in the south-eastern hills. Axe Throwers guard the outer huts; the Witch Doctors and Headhunters hold the heart of the village."] = "Los trols Secacorteza ocupan la aldea de las colinas del sureste. Los lanzahachas vigilan las chozas exteriores; los médicos brujos y los cazadores de cabezas ocupan el centro de la aldea.",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "El círculo interior está al sur del círculo oeste, al este de Stromgarde.",
		["The next guide heads into {zone:1445}."] = "La próxima guía va a {zone:1445}.",
		["The orc stronghold at the eastern end of the road. {npc:2851}, the wind rider master, stands by the gate."] = "La fortaleza orca al final del camino por el este. {npc:2851}, la maestra de jinetes del viento, está junto a la puerta.",
		["The small elementals drift across the flats just west of {npc:2921}'s camp. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards: keep them."] = "Los elementales pequeños vagan por la llanura justo al oeste del campamento de {npc:2921}. Cualquier elemental de roca de la zona puede soltar los Fragmentos de roca elemental de {npc:6868}: guárdalos.",
		["The stone's next task needs Fozruk, a level 42 elite: leave it."] = "La siguiente tarea de la piedra requiere a Fozruk, un élite de nivel 42: déjala.",
		["The {object:138492}"] = "{object:138492}",
		["The {object:2689}"] = "{object:2689}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701} están al fondo de la garganta.",
		["The {object:2702}"] = "{object:2702}",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Entrena mientras estés en {zone:1458}: los instructores están en {object:36070}, {object:36073} y {object:36082} (paladines: {npc:260093}).",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "Al oeste de la cala, los Asaltantes Espinadaga y las hechiceras (38-40) ocupan la orilla: atráelos de uno en uno. Los dos naufragios están en las aguas poco profundas, con las cartas y los diarios dentro; las gemas están en el fondo del mar alrededor de los naufragios.",
		["Zeppelin to the {zone:1458}"] = "Zepelín a {zone:1458}",
		["Zeppelin to {zone:1454}"] = "Zepelín a {zone:1454}",
		["Zeppelin tower"] = "Torre del zepelín",
		["for {npc:5395} in {zone:1443}, in the next guide"] = "para {npc:5395} en {zone:1443}, en la próxima guía",
		["{item:3713}, for \"Swamp Eye\" Jarl in {zone:1445}"] = "{item:3713}, para Jarl \"Ojo de Pantano\" en {zone:1445}",
		["{npc:2771}'s next {quest:678} is against Boulderfist elites: leave it."] = "La siguiente {quest:678} de {npc:2771} es contra élites Puño de Roca: déjala.",
		["{npc:2920}: only if you carry {item:2868} ({skill:164} or the Auction House)"] = "{npc:2920}: solo si llevas {item:2868} ({skill:164} o la casa de subastas)",
		["{object:1661} has no Hunter or Shaman trainer: take the {zone:1454} zeppelin from the same tower instead and train in the city, then take the {zone:1458} zeppelin from the tower outside {zone:1454}'s main gate."] = "{object:1661} no tiene instructor de cazadores ni de chamanes: toma en su lugar el zepelín de {zone:1454} en la misma torre y entrena en la ciudad; luego toma el zepelín de {zone:1458} en la torre de fuera de la puerta principal de {zone:1454}.",
		["{zone:1458} trainers"] = "Instructores de {zone:1458}",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Darkfang spiders"] = "Arañas Colmilloumbrío",
		["For {npc:2519} at {object:3202}, in the next guide"] = "Para {npc:2519} en {object:3202}, en la siguiente guía",
		["Hearth to Shadowprey"] = "Usa la piedra de hogar para ir a la Aldea Cazasombras",
		["Kodo bones and ghosts"] = "Huesos de kodo y fantasmas",
		["Maraudine totems"] = "Tótems Maraudine",
		["Mirefin murlocs"] = "Múrlocs Ancalodo",
		["Pick up the kodo bones scattered across the graveyard, and use the {item:15848} among the bones: the ghosts it draws drop the ghost-o-plasm."] = "Recoge los huesos de kodo esparcidos por el cementerio y usa el {item:15848} entre los huesos: los fantasmas que atrae sueltan el ectoplasma.",
		["Ride back west to Brackenwall with the head."] = "Vuelve al oeste a Murohelecho con la cabeza.",
		["Ride north up the road to the hut by the road north of the graveyard."] = "Ve al norte por el camino hasta la cabaña junto al camino, al norte del cementerio.",
		["Ride on south-west to Shadowprey."] = "Sigue al suroeste hasta la Aldea Cazasombras.",
		["Ride west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely."] = "Vuelve al oeste cruzando el pantano. Los Escupevenenos Colmilloumbrío de las crestas al norte de Murohelecho sueltan las glándulas de veneno. Los Infiltradores de Theramore (35-36) se cuelan por los mismos bosques: usan sigilo, así que fíjate bien.",
		["Slitherblade coast"] = "Costa Filozante",
		["Stinky Ignatz"] = "Ignatz el \"Apestoso\"",
		["Swamp Eye Jarl"] = "\"Ojolodo\" Jarl",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "En el cruce, toma el camino del norte hasta el poblado ogro de Murohelecho.",
		["The Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes."] = "Las arañas Niebla Negra pululan en la entrada de la cueva al noroeste de Murohelecho; todas sueltan ojos.",
		["The next guide takes you back to {zone:1434}."] = "La siguiente guía te lleva de vuelta a {zone:1434}.",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "solo si llevas una {item:3853} ({skill:164} o la casa de subastas)",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}, en el borde sur del poblado, donde entra el camino",
		["{npc:5395} and {npc:5412} stand in the post just west of {npc:11596}'s camp."] = "{npc:5395} y {npc:5412} están en el campamento justo al oeste del de {npc:11596}.",
		["{npc:6791}: the last guide binds here, so this usually ticks at once"] = "{npc:6791}: la guía anterior te vincula aquí, así que esto suele marcarse al instante",
		["{object:20985}, beside the manor"] = "{object:20985}, junto a la mansión",
		["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}, ahora que {npc:4791} ha leído el informe",
} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["Draenethyst crystals"] = "Cristales de draenetista",
		["Fly to {object:3202}"] = "Vuela a {object:3202}",
		["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them."] = "Sigue la costa hacia el sur. Los exploradores naga vadean la orilla y llevan los fardos de juncos; {object:759} burbujea en las colinas justo al este.",
		["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals."] = "Más al norte, los goblins de Ventura y Cía. excavan en la mina al este del camino; mineros, supervisores, peritos y manitas sueltan los cristales.",
		["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then {npc:1514}. Fight them one at a time."] = "Dale los colmillos a Unbagwa y quédate a su lado: llama a tres oleadas de gorilas y luego a {npc:1514}. Lucha contra ellos de uno en uno.",
		["Hearth to {object:3202}"] = "Piedra de hogar a {object:3202}",
		["Into the {zone:1435}"] = "Hacia {zone:1435}",
		["Jungle stalkers"] = "Acechadores de la selva",
		["Mistvale gorillas"] = "Gorilas de Velo de Bruma",
		["Naga shore and the {object:759}"] = "Costa de los naga y {object:759}",
		["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "Al noreste de Velo de Bruma, los seguidores de Zanzil acampan en la jungla; cualquiera de ellos puede llevar la mezcla.",
		["Pirate ghosts"] = "Fantasmas piratas",
		["Ride north to the Skullsplitter ruins east of the Venture Co. mine; pull the headhunters and berserkers one at a time. {npc:1059} guards the south-western ruins, and one pile of trophy skulls stands on the ruins' north side. Every Skullsplitter can drop a tusk or a necklace: the necklaces are the slow part, so keep killing in the warriors' camp north of the ruins until you have them all."] = "Cabalga al norte hasta las Ruinas de Zul'Mamwe, de los Machacacráneos, al este de la mina de Ventura y Cía.; atrae a los rebanacabezas y rabiosos de uno en uno. {npc:1059} guarda las ruinas del suroeste, y una pila de cráneos trofeo está en el lado norte de las ruinas. Cualquier Machacacráneos puede soltar un colmillo o un collar: los collares son lo lento, así que sigue matando en el campamento de guerreros al norte de las ruinas hasta tenerlos todos.",
		["Ride north up the road to the hunters' camp."] = "Cabalga al norte por el camino hasta el campamento de los cazadores.",
		["Ride north up the road; the hunters camp on the hill above the river."] = "Cabalga al norte por el camino; los cazadores acampan en la colina sobre el río.",
		["Ride north-west to {object:3202}."] = "Cabalga al noroeste hasta {object:3202}.",
		["Ride west to {object:3202}."] = "Cabalga al oeste hasta {object:3202}.",
		["Sawtooth crocolisks"] = "Crocoliscos Denteserra",
		["Sawtooth snappers"] = "Sacudidores Denteserra",
		["Skullsplitter warriors"] = "Guerreros Machacacráneos",
		["The Bloodsail ships"] = "Los barcos Velasangre",
		["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "Los gorilas deambulan por el valle alrededor de Unbagwa. Los ancianos sueltan las tripas; cualquiera puede soltar un colmillo.",
		["The last skulls are in the ruins a short ride west, on the way back to {object:3202}."] = "Los últimos cráneos están en las ruinas a poca distancia al oeste, de camino de vuelta a {object:3202}.",
		["The next guide starts here and takes you to {zone:1446}."] = "La siguiente guía empieza aquí y te lleva a {zone:1446}.",
		["The next trophy skulls stand in the small ruins just north of the warriors' camp."] = "Los siguientes cráneos trofeo están en las pequeñas ruinas justo al norte del campamento de guerreros.",
		["The snappers line the strand south of the post."] = "Los sacudidores recorren la playa al sur del puesto.",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast."] = "Los acechadores de la selva cazan en la jungla al sur de {object:3202}, hacia la costa oeste.",
		["Venture Co. mine"] = "Mina de Ventura y Cía.",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them."] = "Al oeste de la expedición, los jefes Cabellesangre {npc:1061} y {npc:1062} están juntos en las Ruinas de Zul'Kunda. Limpia antes a sus guardias y luego atráelos.",
		["Zanzil's camps"] = "Campamentos de Zanzil",
		["Zul'Kunda"] = "Zul'Kunda",
		["Zul'Mamwe"] = "Zul'Mamwe",
		["for Stoley in {zone:1446}"] = "para Stoley en {zone:1446}",
		["for a later stop in the {zone:1435}"] = "para una parada posterior en {zone:1435}",
		["for later: the {zone:1425}, around level 48"] = "para más tarde: {zone:1425}, alrededor del nivel 48",
		["the {object:2076}"] = "{object:2076}",
		["the {object:2076}, beside {npc:2497}"] = "{object:2076}, junto a {npc:2497}",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Eastern Wastewander camps"] = "Campamentos Deambulador del este",
		["Fly to {object:3202}"] = "Vuela a {object:3202}",
		["Grimtotem camp"] = "Campamento Tótem Siniestro",
		["Keep riding west to the coast. The Coast Crawl Deepseers and Snapclaws on the beaches drop OOX-22/FE's distress beacon about one kill in forty: if one drops, use it to start the quest."] = "Sigue cabalgando hacia el oeste hasta la costa. Los Videnistas y Quebradores Reptacostas de las playas sueltan la baliza de socorro de OOX-22/FE aproximadamente una de cada cuarenta muertes: si cae, úsala para empezar la misión.",
		["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "Al norte de los gnolls, los ogros ocupan un puesto en lo alto de una colina; atrae hacia ti a los magos ogros. El cobalto está en los montículos de tierra alrededor del puesto, y el pergamino está en el suelo, dentro.",
		["Ride north-east to the goblin harbour on the coast."] = "Cabalga hacia el noreste hasta Puerto Bonvapor, el puerto goblin de la costa.",
		["Ride west into the middle of {zone:1444}. Kill a {npc:5308}, use {item:10699} on its body and kill the spirit that rises."] = "Cabalga hacia el oeste hasta el centro de {zone:1444}. Mata a un {npc:5308}, usa {item:10699} en su cuerpo y mata al espíritu que surge.",
		["Riding at 40"] = "Equitación a nivel 40",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel; no Skyborne riding trainer is known, so Skyborne try {npc:4752} too. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each."] = "Equitación requiere nivel 40 y cuesta 100 de oro; al aprenderla recibes una montura. {npc:4752} entrena a los orcos en {object:172958}, junto a la perrera de {npc:3362}; no se conoce instructor de equitación Cielonato, así que los cielonatos también deben probar con {npc:4752}. Las demás monturas de tu raza cuestan 20 de oro cada una: Coleccionables, Monturas · Nivel 40 tiene una guía para cada una.",
		["Rogue Vale screechers"] = "Pícaros estridadores del valle",
		["South along the coast, the Southsea pirates hold the cove. {npc:7883} and the stolen cargo are on the docks at its far end. Any pirate can drop a hat, the kidnappers most often."] = "Al sur por la costa, los piratas del Mar del Sur ocupan la cala. {npc:7883} y el cargamento robado están en los muelles del fondo. Cualquier pirata puede soltar un sombrero; los secuestradores, más a menudo.",
		["Southern Gordunni ruins"] = "Ruinas Gordunni del sur",
		["Southern Wastewander camps"] = "Campamentos Deambulador del sur",
		["Sprite darters and Woodpaw alphas"] = "Duendes dardo y Alfas Zarpaleña",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "Los tauren Tótem Siniestro acampan junto a la arboleda de los duendes dardo; asaltantes, naturalistas y chamanes llevan cuernos.",
		["The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane."] = "Los gnolls Zarpaleña acampan en las colinas justo al noroeste de Mojache; cualquiera puede soltar una crin.",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber."] = "La colmena Zukk'ash excava en las colinas al sureste del campamento; {quest:7731} espera en su cámara más profunda.",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "El mapa de batalla está en el campamento Zarpaleña al sur de Mojache.",
		["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour."] = "Los duendes dardo revolotean sobre la arboleda justo al oeste de Mojache; casi todos sueltan un ala. Los Alfas Zarpaleña dirigen los campamentos al suroeste: mátalos antes de una hora.",
		["The {object:3202} zeppelin leaves from the tower just north-east of {zone:1454}'s main gate."] = "El zepelín a {object:3202} sale de la torre justo al noreste de la puerta principal de {zone:1454}.",
		["The {zone:1454} zeppelin leaves from the tower beside {object:3202}; it lands just outside {zone:1454}'s main gate."] = "El zepelín a {zone:1454} sale de la torre junto a {object:3202}; aterriza justo fuera de la puerta principal de {zone:1454}.",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "Lobos: {npc:3362}, junto a {npc:4752}.",
		["Woodpaw battle map"] = "Mapa de batalla Zarpaleña",
		["Woodpaw north camp"] = "Campamento Zarpaleña del norte",
		["Zeppelin to {object:3202}"] = "Zepelín a {object:3202}",
		["Zeppelin to {zone:1454}"] = "Zepelín a {zone:1454}",
		["Zeppelin tower"] = "Torre del zepelín",
		["for the {zone:1425}, around level 48"] = "para {zone:1425}, hacia el nivel 48",
		["for {zone:1454}, around level 45"] = "para {zone:1454}, hacia el nivel 45",
		["the {object:150075} in the square"] = "{object:150075} de la plaza",
		["water pouches in your bags"] = "bolsas de agua en tus bolsas",
		["{npc:3690}, riding trainer"] = "{npc:3690}, instructor de equitación",
		["{npc:4752}, riding trainer"] = "{npc:4752}, instructor de equitación",
		["{npc:4773}, riding trainer"] = "{npc:4773}, instructora de equitación",
		["{npc:7953}, riding trainer"] = "{npc:7953}, instructor de equitación",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115}: para {zone:1454}, hacia el nivel 45",
		["{npc:8579}: the screechers live in {zone:1444}"] = "{npc:8579}: los Pícaros estridadores del valle viven en {zone:1444}",
		["{quest:2863}: one hour from now"] = "{quest:2863}: dentro de una hora",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Dragon caves"] = "Cuevas de dragones",
		["Fly to {object:3202}"] = "Vuela a {object:3202}",
		["Forest walkers"] = "Caminabosques",
		["Frayfeather hippogryphs"] = "Hipogrifos Plumavieja",
		["Monstrous Crawlers"] = "Reptadores monstruosos",
		["Murlocs of the Misty Reed"] = "Múrlocs de Juncobruma",
		["North-west along the road, the Rage Scar yetis live around the caves in the hills. Any of them can also drop a {quest:7738}, which starts a quest of its own."] = "Al noroeste por el camino, los Yetis Estigmodio viven alrededor de las cuevas de las colinas. Cualquiera puede soltar también una {quest:7738}, que inicia su propia misión.",
		["Northspring harpies"] = "Arpías Nortearroyo",
		["Onyxia's eggs"] = "Huevos de Onyxia",
		["Rage Scar yetis"] = "Yetis Estigmodio",
		["Ride back north to Brackenwall."] = "Vuelve cabalgando al norte, a Murohelecho.",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "Cabalga hacia el oeste por el camino; el pergamino está a la orilla del agua, en el extremo oeste del pantano.",
		["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with {item:18904} first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "Elementales marinos y Rocíos del mar recorren la orilla alrededor del muelle. Dispara primero a los gigantes con {item:18904}: encogidos, pierden su fuerza de élite. Los Zancacostas vadean en el agua; los Caminantes de la tierra y los Gigantes del risco recorren las colinas más al norte.",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "Al sur del valle, los Hipogrifos Plumavieja anidan en las laderas; casi todos sueltan tendones y fragmentos metálicos.",
		["Sprite darters and forest walkers"] = "Duendes dardo y Caminabosques",
		["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "Los Múrlocs del pantano viven en la playa al sur del puesto; los Vomitatintas están en la orilla al este y los Comecarnes más al oeste, alrededor de las chozas de la orilla oeste.",
		["The Monstrous Crawlers walk the beaches of the east coast, few and far between: kill every one you see on the way south."] = "Los Reptadores monstruosos recorren las playas de la costa este, pocos y dispersos: mata a todos los que veas de camino al sur.",
		["The Northspring harpies nest on the ridges in the far north-west. They are 48-50, a few levels above you: the Windcallers heal, so kill them first and pull one at a time."] = "Las Arpías Nortearroyo anidan en las crestas del extremo noroeste. Son de nivel 48-50, unos niveles por encima de ti: las Clamavientos curan, así que mátalas primero y atráelas de una en una.",
		["The same murlocs again, plus the Oracles, who stay near the huts on the western shore."] = "Los mismos múrlocs otra vez, más los Oráculos, que se quedan cerca de las chozas de la orilla oeste.",
		["The small Horde post on the southern shore."] = "El pequeño puesto de la Horda en la orilla sur.",
		["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "Los duendes dardo revolotean sobre la arboleda justo al oeste del campamento y llevan los {item:9589}; los Caminabosques deambulantes, un poco más al oeste, llevan los Troncos astillados.",
		["The zeppelin to {zone:1454} leaves from the tower beside {object:3202}; it lands just north-east of {zone:1454}'s main gate."] = "El zepelín a {zone:1454} sale de la torre junto a {object:3202}; aterriza justo al noreste de la puerta principal de {zone:1454}.",
		["Zeppelin to {zone:1454}"] = "Zepelín a {zone:1454}",
		["Zeppelin tower"] = "Torre del zepelín",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "para {npc:5598} en {zone:1425}, hacia el nivel 48",
		["for the {object:2555} in {zone:1445}, later in this guide"] = "para {object:2555} en {zone:1445}, más adelante en esta guía",
		["for the {zone:1425} owlbeasts, around level 48"] = "para las lechubestias de {zone:1425}, hacia el nivel 48",
		["the {object:2555}"] = "{object:2555}",
		["{npc:4500} is elite: grouping up is advised. Beat him down until he gives up, then report to {npc:4501}."] = "{npc:4500} es élite: se recomienda ir en grupo. Golpéalo hasta que se rinda y luego informa a {npc:4501}.",
		["{npc:7875}: for {npc:7010} in {zone:1454}, around level 50"] = "{npc:7875}: para {npc:7010} en {zone:1454}, hacia el nivel 50",
		["{object:172958}, then the {object:172960} and the {object:172961}."] = "{object:172958}, luego {object:172960} y {object:172961}.",
		["{quest:7738}, a rare drop"] = "{quest:7738}, botín raro",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Dark Iron Lookouts"] = "Vigías Hierro Negro",
		["Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive."] = "Más al sur, el equipo de análisis de Patagolpe está en la entrada de una colmena Centipaar.",
		["Greater Lava Spiders"] = "Arañas de lava abrasadoras",
		["Heavy War Golems patrol the Cauldron below Kalaran and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the {item:11818}: keep it."] = "Los Gólems de guerra pesados patrullan La Caldera bajo Kalaran y sueltan el aceite; los Elementales de magma y los Elementales de fuego que vagan entre ellos sueltan los corazones. Los Capataces Hierro Negro y los Esclavistas Hierro Negro arrean a los esclavos por los caminos; un Esclavista puede soltar la {item:11818}: guárdala.",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "Su siguiente encargo pide el {item:10552} de fieles élite: déjalo.",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "Solo con la {item:11818}: vuelve al este hasta el {object:173265} de la excavación.",
		["Scrimshank's gear"] = "Equipo de análisis de Patagolpe",
		["South down the road again."] = "Vuelve al sur por el camino.",
		["South-east of Gadgetzan the Wastewander bandits camp in the dunes; {npc:7847} stands in the eastern camp."] = "Al sureste de Gadgetzan acampan los Bandidos Deambuladores en las dunas; {npc:7847} está en el campamento del este.",
		["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "Los Vigías Hierro Negro vigilan las crestas alrededor de las torres de guardia al sur de La Caldera; uno de cada diez, más o menos, lleva el {item:18960}.",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "Los Vapoherreros Hierro Negro trabajan en los hornos del centro de La Caldera; la mitad lleva una {item:10551} y uno de cada diez la {item:18959}. Los esclavos, Esclavistas y Capataces también llevan dagas.",
		["The Greater Lava Spiders roam the plateaus and lava pools in the south-west of the gorge."] = "Las Arañas de lava abrasadoras recorren las mesetas y pozas de lava del suroeste de la garganta.",
		["The Steamsmiths' furnaces"] = "Los hornos de los Vapoherreros",
		["The {object:179827} board"] = "El tablón {object:179827}",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "Al oeste de Gadgetzan, usa la {item:8584} junto a la charca del campamento trol.",
		["West of the compound the cactus creatures fill the valley; only the Dew Collectors carry a dew gland. Most mobs in {zone:1446} can drop OOX-17/TN's distress beacon, rarely: keep it if you see one."] = "Al oeste de la base, las criaturas cactus llenan el valle; solo los Colectores de rocío Cardizal llevan una glándula de rocío. Casi todos los enemigos de {zone:1446} pueden soltar, rara vez, el Localizador de emergencia OOX-17/TN: guárdalo si te sale uno.",
		["West, the Centipaar insects swarm around their hives; any of them drops the parts."] = "Al oeste, los insectos Centipaar pululan alrededor de sus colmenas; cualquiera de ellos suelta los trozos.",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "el {item:8526} crece en {zone:1425}, hacia el nivel 48",
		["the {object:150075} in the square"] = "el {object:150075} de la plaza",
		["the {object:173265}"] = "el {object:173265}",
		["{item:11818}, a rare drop"] = "{item:11818}, botín poco común",
		["{item:8623}, a rare drop"] = "{item:8623}, botín poco común",
		["{npc:5955}'s escort"] = "Escolta de {npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, junto al maestro de jinetes del viento",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["East of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south."] = "Al este del camino, los jabalíes Cenicrín y los gruñones hozan en las laderas junto a los basiliscos Rocarroja. Evita a los jabinfernos de nivel 52, más al sur.",
		["East of the village, the violet flower grows in the hills."] = "Al este del poblado, la flor violeta crece en las colinas.",
		["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "Sigue los caminos hacia el este a través de {zone:1425} hasta el poblado trol de la costa este.",
		["Grind to 48"] = "Sube al nivel 48",
		["Highvale"] = "Vallealto",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "Al norte por la costa, la cesta de merienda de {npc:14731} está en el islote; la vigila un {npc:14748}.",
		["OOX-09/HL"] = "OOX-09/HL",
		["Only if you are not level 48 yet."] = "Solo si aún no eres de nivel 48.",
		["Ride back north to the bloodmages."] = "Vuelve al norte con los magos sangrientos.",
		["Saltwater Snapjaws"] = "Quijafortes Aguasalada",
		["Silvermane Howlers"] = "Aulladores Melenargenta",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "Al sur del refugio, los trols Secacorteza ocupan sus poblados. Todos llevan un cráneo: con veinte, usa {item:15002} para hacer el Pico cargado de Nimboya y clávalo dentro del poblado.",
		["South-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "Al suroeste, los aulladores Melenargenta recorren las colinas al este de los poblados Secacorteza.",
		["The Vilebranch temples"] = "Los templos Vilrama",
		["The big turtles crawl along the beaches north of the village. {npc:2491}'s port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it."] = "Las tortugas grandes se arrastran por las playas al norte del poblado. Las botellas de oporto de {npc:2491} también están en estas playas, pero su misión no forma parte de esta ruta. Un quijaforte puede soltar, rara vez, la baliza de socorro de OOX-09/HL: guárdala.",
		["The bloodmages"] = "Los magos sangrientos",
		["The central hills"] = "Las colinas centrales",
		["The eastern slopes"] = "Las laderas del este",
		["The five quests share the same parts: gather them all in one sweep. West of the road the {npc:5982} vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills."] = "Las cinco misiones piden las mismas partes: reúnelas todas de una pasada. Al oeste del camino, los buitres {npc:5982}, las hienas risitas hambrientas, los aguijoneros Scorpok y los basiliscos Ojo de la Muerte comparten las colinas.",
		["The northern beasts"] = "Las bestias del norte",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "Sus misiones siguientes piden otra vez las mismas partes a cambio de un objeto de mejora y no dan experiencia: déjalas.",
		["Vilebranch soothsayers"] = "Adivinos Vilrama",
		["Vulture hills"] = "Colinas de los buitres",
		["for {npc:6986} in {zone:1454}, around level 50"] = "para {npc:6986} en {zone:1454}, hacia el nivel 50",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "para {npc:7825} en {zone:1458}, hacia el nivel 50",
		["grind on {npc:5982} at the northern hills, {zone:1419}"] = "mata {npc:5982} en las colinas del norte, {zone:1419}",
		["{item:8704}, a rare drop"] = "{item:8704}, botín poco común",
		["{npc:14731}'s lunch"] = "El almuerzo de {npc:14731}",
		["{npc:6741}: for {zone:1456}, around level 50"] = "{npc:6741}: para {zone:1456}, hacia el nivel 50",
		["{npc:7801}'s camp"] = "Campamento de {npc:7801}",
		["{npc:7825}, the {object:36126}"] = "{npc:7825}, {object:36126}",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["Back north-east to {npc:8420}."] = "Vuelve al noreste con {npc:8420}.",
		["Back to {object:3202}"] = "De vuelta a {object:3202}",
		["Follow the road south; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "Sigue el camino hacia el sur; los basiliscos toman el sol en las rocas al este, en medio de la selva. Sus fragmentos caen a menudo.",
		["Frayfeather Hippogryphs"] = "Hipogrifos Plumavieja",
		["Highborne and Haldarr satyrs"] = "Apariciones de Altonato y sátiros Haldarr",
		["Ironjaw Basilisks"] = "Basiliscos Quijahierro",
		["Keep the deliveries for {npc:4046}, {npc:8659} and {npc:6522}: you pass {zone:1456}, {zone:1454} and the {zone:1458} later."] = "Guarda las entregas para {npc:4046}, {npc:8659} y {npc:6522}: pasarás por {zone:1456}, {zone:1454} y {zone:1458} más adelante.",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "Guarda {quest:3444}: el cofre de {npc:7771} se abre en una visita posterior.",
		["Only once all three robots are home"] = "Solo cuando los tres robots estén en casa",
		["Ride into {zone:1447}"] = "Entra en {zone:1447}",
		["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry {npc:8420}'s rune."] = "Cabalga al suroeste hasta las ruinas. Las cuatro tablillas están entre las ruinas, custodiadas por nagas Látigo de Ira; cualquier sirena o mirmidón Látigo de Ira puede llevar la runa de {npc:8420}.",
		["Sea elementals"] = "Elementales marinos",
		["Sprite Darters"] = "Duendes dardo",
		["Take the zeppelin back to {zone:1454}."] = "Toma el zepelín de vuelta a {zone:1454}.",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "Las apariciones de Altonato rondan las ruinas justo al norte del santuario; los sátiros Haldarr acampan un poco más al norte.",
		["The Land Walkers and Cliff Giants roam the hills north of the dock. Zap each one with {item:18904} first: shrunken, they are no longer elite. Every zapped giant drops residue; use the Muisek Vessel on its body too."] = "Los caminantes de la tierra y los gigantes del risco recorren las colinas al norte del muelle. Primero, dispara a cada uno con {item:18904}: encogidos, ya no son élite. Cada gigante encogido suelta residuo; usa también la Vasija de muisek gigante de montaña sobre su cuerpo.",
		["The Sea Elementals and Sea Sprays wash along the shore around the dock."] = "Los elementales marinos y los rocíos del mar recorren la orilla alrededor del muelle.",
		["The blood elves' camp lies just south of {npc:8420}. His four pieces of equipment lie in the crates around the camp."] = "El campamento de los elfos de sangre está justo al sur de {npc:8420}. Sus cuatro piezas de equipo están en las cajas alrededor del campamento.",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "Los dragones feéricos revolotean por el bosque justo al oeste del campamento. Usa la vasija sobre cada uno que mates.",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "Los hipogrifos anidan en las colinas al suroeste del campamento. Mata uno y usa la Vasija de muisek hipogrifo sobre su cuerpo.",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "Los antárboles deambulan por los caminos del bosque entre el campamento y el centro de {zone:1444}; hay pocos, así que búscalos por los senderos.",
		["The {object:2076} beside {npc:2519}"] = "{object:2076} junto a {npc:2519}",
		["To {object:3202}"] = "A {object:3202}",
		["Undamaged Hippogryph Feathers"] = "Plumas de hipogrifo sin estropear",
		["Wandering Forest Walkers"] = "Caminabosques deambulantes",
		["Zapped giants"] = "Gigantes encogidos",
		["Zeppelin to {zone:1454}"] = "Zepelín a {zone:1454}",
		["{npc:6986}, the Drag"] = "{npc:6986}, La Calle Mayor",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776}: los osos están en {zone:1448}",
		["{npc:7825} stands in the {object:36082}."] = "{npc:7825} está en {object:36082}.",
		["{npc:7876}'s tar and Pestlezugg's samples come from {zone:1449}."] = "El alquitrán de {npc:7876} y las muestras del Alquimista Morterozugg vienen de {zone:1449}.",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, junto al maestro de jinetes del viento",
		["{npc:8395}, at the east edge of the camp: no experience, only a teleport to Azshara Tower"] = "{npc:8395}, en el borde este del campamento: no da experiencia, solo un teletransporte a la torre de Azshara",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{quest:3761} is gathered in the next guide; {npc:4046}'s payment goes back to {npc:8587} later."] = "{quest:3761} se reúne en la siguiente guía; el pago de {npc:4046} se entrega a {npc:8587} más adelante.",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Black Broodlings"] = "Cachorrillos negros",
		["Bloodpetal Flayers"] = "Despellejadores pétalo de sangre",
		["Cross the south of the crater to the pylon on the western cliffs."] = "Cruza el sur del cráter hasta el pilón de los acantilados occidentales.",
		["Darrowshire Spirits"] = "Espíritus de Villa Darrow",
		["Eastern Pylon"] = "Pilón del este",
		["Escort {npc:9999}"] = "Escolta a {npc:9999}",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "Sigue los acantilados hacia el sur hasta {quest:3821}, la colina de los ogros Pirontraña. Los restos de {npc:9136} están al pie.",
		["Free Darrowshire Spirits: talk to them"] = "Libera Espíritus de Villa Darrow: habla con ellos",
		["From here on pick up every Power Crystal (blue, green, red, yellow) and every {quest:3761} pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."] = "A partir de aquí recoge cada Cristal de poder (azul, verde, rojo, amarillo) y cada montón de {quest:3761} que encuentres: 25 de tierra en total, 20 para Hamuul y 5 para Morterozugg.",
		["Gorillas"] = "Gorilas",
		["Into the {zone:1427}"] = "Hacia {zone:1427}",
		["Into {zone:1449}"] = "Hacia {zone:1449}",
		["Keep the bait: {npc:9684} is level 56, and the second loop passes his lair."] = "Guarda el cebo: {npc:9684} es de nivel 56 y la segunda vuelta pasa por su guarida.",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "Guarda {quest:4147}, de {npc:9118}, y la carta de {npc:8737} para guías posteriores.",
		["Lar'korwi Mates"] = "Amigos de Lar'korwi",
		["Lashers and Threshers"] = "Latigadores y Trilladores",
		["North of Torwa, a dead Threshadon lies by the water."] = "Al norte de Torwa yace un trillanodonte muerto junto al agua.",
		["Northern Pylon"] = "Pilón del norte",
		["Out of the refuge"] = "Fuera del refugio",
		["Pestlezugg's next quest needs the {npc:10041}, an elite boss. Skip it."] = "La siguiente misión de Morterozugg requiere a la {npc:10041}, un jefe élite. Omítela.",
		["Power Crystals and soil"] = "Cristales de poder y tierra",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "Baja por el lado este del cráter hasta el pilón de los acantilados orientales.",
		["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "Cabalga hacia el norte por el lado este. La jungla está llena de Latigadores y Trilladores pétalo de sangre.",
		["Ride south-west along the western cliffs. {npc:9167} fly over the west side, and Bloodpetal Trappers grow in the same jungle."] = "Cabalga hacia el suroeste por los acantilados occidentales. Los {npc:9167} vuelan sobre el lado oeste, y los Tramperos pétalo de sangre crecen en la misma jungla.",
		["Ride west to the dig site. {npc:7039} golems (53) stomp around it and drop the shards often; the {quest:4296} stands in its middle among the Thaurissan dwarves. Copy it."] = "Cabalga hacia el oeste hasta la excavación. Los gólems {npc:7039} (53) patrullan a su alrededor y sueltan a menudo los fragmentos; {quest:4296} está en el centro, entre los enanos Thaurissan. Cópiala.",
		["South of the hot springs, Stegodons graze and Dinosaur Bones drop from them or lie on the ground; Diemetradons nearby carry the scales {npc:9998} wants. Ravasaurs hunt in packs in the south-west: their claws are for {npc:8659}, and now and then one carries a Mangled Journal (a rare drop: take its quest only if you get one). Avoid Gruff, a level 57 Stegodon."] = "Al sur de las aguas termales pastan los Stegodons, que sueltan Huesos de dinosaurio (también los hay en el suelo); los Diemetradones de al lado llevan las escamas que quiere {npc:9998}. Los Ravasaurios cazan en manada en el suroeste: sus garras son para {npc:8659}, y de vez en cuando uno lleva Un diario destrozado (botín raro: acepta su misión solo si te sale). Evita a Gruff, un Stegodon de nivel 57.",
		["Stegodons and ravasaurs"] = "Stegodons y ravasaurios",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5401}: Scourgestones only drop while you wear it."] = "Coge una {object:176092} del cajón junto a Derrington para {quest:5096}, que harás a la vuelta. Equípate {quest:5401}: las Piedras de la Plaga solo caen mientras lo llevas puesto.",
		["Termite mounds"] = "Montículos de termitas",
		["Thaurissan dig site"] = "Excavación de Thaurissan",
		["The Gorishi hive"] = "La colmena Gorishi",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "Los Amigos de Lar'korwi merodean por la jungla al noroeste de {npc:9619}.",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "La cabeza de la muñeca y sus dos mitades están en las casas alrededor de {npc:10926}; únelas desde tus bolsas.",
		["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "El cajón de la expedición está en un campamento abandonado de la jungla oriental.",
		["The expedition's lost equipment lies in the south-west jungle."] = "El equipo perdido de la expedición está en la jungla del suroeste.",
		["The gorillas live on the north-east plateau. Stay out of the deepest cave: {npc:9622} lives there."] = "Los gorilas viven en la meseta del noreste. No entres en la cueva más profunda: allí vive {npc:9622}.",
		["The next guide starts here, at the chapel's flight master."] = "La siguiente guía empieza aquí, en el maestro de vuelo de la capilla.",
		["The pylon stands on the slope east of the refuge."] = "El pilón está en la ladera al este del refugio.",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "La balsa está en la orilla del lago del sureste; la mochila pequeña está en el agua, a su lado.",
		["The silithid hive fills the south of the crater. Gorishi wasps and workers drop the scent gland; use the Scraping Vial on the egg mass inside the first chamber. The Hive Queen at the bottom is an elite boss: stay out of her chamber. {npc:9166} nest on the cliffs above the hive; their scales are for {npc:9998}."] = "La colmena silítida ocupa el sur del cráter. Las Avispas y los Obreros Gorishi sueltan la glándula de olor; usa el Vial de raspadura en la masa de huevos de la primera cámara. La Reina de la colmena Gorishi, al fondo, es un jefe élite: no entres en su cámara. Los {npc:9166} anidan en los acantilados sobre la colmena; sus escamas son para {npc:9998}.",
		["The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the {item:11834}."] = "Los pozos de alquitrán están justo al sur del refugio. Las Bestias Tar, los Rondadores Tar y los Trepadores Tar sueltan el {item:11834}.",
		["The wooden sign beside {npc:9997}"] = "El cartel de madera junto a {npc:9997}",
		["Use the Mangled Journal to start it"] = "Usa Un diario destrozado para empezarla",
		["Western Pylon"] = "Pilón del oeste",
		["Western jungle"] = "Jungla occidental",
		["{item:11116}, a rare drop"] = "{item:11116}, botín raro",
