		["Back to the Den"] = "Vuelve a El Cubil",
		["Back to {npc:5875} in the {object:172960}. Use the {item:7464} on the summoning circle there and defeat the voidwalker to bind it."] = "Vuelve con {npc:5875} en {object:172960}. Usa {item:7464} en el círculo de invocación de allí y derrota al abisario para vincularlo.",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "Los fieles Filo Ardiente ocupan las cuevas de {quest:827}; cualquiera de ellos suelta {item:4871}. {npc:3204}, un brujo de nivel 14, está en lo más hondo y suelta {item:4903}.",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Los acechadores viles recorren la ladera bajo la cueva, en el lado norte del valle.",
		["Follow the road north toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "Sigue el camino hacia el norte, hacia {zone:1454}. {npc:3293} acampa junto a él; los sacos robados están a lo largo del camino, al sur de él.",
		["Free {npc:275811} and see her safely out of the crag"] = "Libera a {npc:275811} y sácala sana y salva del risco",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle."] = "Ve al sur por las islas. Los ídolos loa están por todas las islas del sur; los trols de vudú y los trols maléficos las ocupan y sueltan los colgantes embrujados. {quest:826} y la jaula de Minshina están en la isla más al sur.",
		["Hit the sleeping peons north of the Den with the {item:16114}."] = "Golpea con {item:16114} a los peones dormidos al norte de El Cubil.",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "Dentro de la cueva, sigue recto en la primera bifurcación, luego a la derecha, y sigue el arroyo que tienes a la izquierda hasta la cascada: el pico brilla junto al agua, detrás de una columna de roca.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Dentro de la cueva, sigue la pared derecha durante todo el recorrido, cruzando el arroyo: {npc:3183} espera al final.",
		["Makrura and crawlers"] = "Makrura y correspumas",
		["Makrura and surf crawlers line the beaches north-east of Sen'jin."] = "Los makrura y los correspumas pueblan las playas al noreste del poblado Sen'jin.",
		["North end of the valley"] = "Extremo norte del valle",
		["Prickly pears"] = "Peras espinosas",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "Los jabaespines y exploradores ocupan las chozas al oeste del pueblo; los correpolvos y guardias de batalla ocupan los campamentos más al oeste.",
		["Ridgeshade spiders"] = "Arañas crestasombra",
		["South-east shore"] = "Orilla sureste",
		["Spitelash naga"] = "Nagas Látigo de Ira",
		["Talk to {npc:3191}"] = "Habla con {npc:3191}",
		["Tame it with the {item:15908}"] = "Domestícalo con {item:15908}",
		["The foreman stands at the lumber pile east of the Den."] = "El supervisor está junto al montón de madera, al este de El Cubil.",
		["The prickly pears grow among the quilboar huts just west of town."] = "Las peras espinosas crecen entre las chozas de los jabaespines, justo al oeste del pueblo.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Las armas están alrededor de El Cubil y del campo de entrenamiento; los jabalíes jaspeados recorren todo el fondo del valle.",
		["The wreckage"] = "Los restos",
		["Thunder lizards"] = "Truenagartos",
		["Thunder lizards across the river"] = "Truenagartos al otro lado del río",
		["Training weapons and boars"] = "Armas de entrenamiento y jabalíes",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there."] = "Cruza vadeando a la isla del norte de las Islas del Eco. La Matriarca ronda entre los raptores de allí.",
		["Wade back west to the shore south of Sen'jin. Durotar Tigers roam it and the Taillasher eggs sit in nests along the beach."] = "Vuelve vadeando al oeste hasta la orilla al sur del Poblado Sen'jin. Por ella rondan los Tigres de Durotar, y los Huevos de Colazote están en nidos a lo largo de la playa.",
		["Wake {quest:5441} with the {item:16114}"] = "Despierta a los {quest:5441} con {item:16114}",
		["the {object:654925} on the ground beside her"] = "{object:654925}, en el suelo a su lado",
		["{npc:10176}, where you start"] = "{npc:10176}, donde empiezas",
		["{npc:265809}'s campfire"] = "La hoguera de {npc:265809}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}: solo encantadores; el residuo se obtiene desencantando colgantes embrujados",
		["{npc:266940}, on the east side of town"] = "{npc:266940}, en el lado este del pueblo",
		["{npc:275666}, a young sea giant, walks {zone:1411}'s north coast, north of the naga beach. {npc:275666} is elite: grouping up is advised."] = "{npc:275666}, un gigante de mar joven, recorre la costa norte de {zone:1411}, al norte de la playa de los naga. {npc:275666} es élite: se recomienda ir en grupo.",
		["{npc:3102} hooves"] = "Pezuñas de {npc:3102}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}: {npc:275666}, un gigante de mar élite",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} está nada más entrar en la cueva; {npc:3159}, al fondo de la cueva, detrás de él.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} espera dentro de El Cubil, el edificio justo al oeste de {npc:10176}.",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, en la atalaya",
		["{npc:3153}, the warrior trainer beside the Den"] = "{npc:3153}, el instructor de guerreros, junto a El Cubil",
		["{npc:3154}, the hunter trainer beside the Den"] = "{npc:3154}, el instructor de cazadores, junto a El Cubil",
		["{npc:3155}, the rogue trainer in the Den"] = "{npc:3155}, el instructor de pícaros, en El Cubil",
		["{npc:3156}, the warlock trainer at the back of the cave"] = "{npc:3156}, el instructor de brujos, al fondo de la cueva",
		["{npc:3157}, the shaman trainer beside the Den"] = "{npc:3157}, el instructor de chamanes, junto a El Cubil",
		["{npc:3159}, at the back of the cave"] = "{npc:3159}, al fondo de la cueva",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} yace herido al pie de las colinas, al noroeste de El Cubil.",
		["{npc:3294}, by the inn"] = "{npc:3294}, junto a la posada",
		["{npc:3706}, for {npc:6018} in {zone:1454}: keep it"] = "{npc:3706}, para {npc:6018} en {zone:1454}: guárdala",
		["{npc:3707}, the priest trainer at the Den"] = "{npc:3707}, el instructor de sacerdotes, en El Cubil",
		["{npc:5884}, the mage trainer, at the entrance to the Den"] = "{npc:5884}, la instructora de magos, en la entrada de El Cubil",
		["{npc:5887} stands just outside the Den."] = "{npc:5887} está justo a la salida de El Cubil.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}: {npc:5873} y tu {item:5175}",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786} está en el camino, en la salida este del valle.",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, junto al fuego de cocina",
		["{quest:790}, a large scorpid, prowls the slope south of {npc:3287} among the Scorpid Workers; pick the Cactus Apples by the cactuses on the way."] = "{quest:790}, un escórpido grande, ronda la ladera al sur de {npc:3287} entre los trabajadores escórpidos; recoge las manzanas de cactus junto a los cactus por el camino.",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} acampa en la colina al oeste de la playa de los naga, al sur de {quest:827}.",
} end)()
t.guides["forever/horde/orc-troll/02-the-barrens"] = (function() return {
		["Back to the pirate camp: the boots are in the crate marked {object:3767} at the camp's south end, the lens in the Fragile crate just east of it."] = "Vuelve al campamento pirata: las botas están en la caja marcada {object:3767}, en el extremo sur del campamento, y la lente, en la caja frágil justo al este.",
		["Plainstriders and raptors"] = "Zancudos de llanura y raptores",
		["Razormane camp"] = "Campamento Crines de Acero",
		["Southsea beach"] = "Playa del Mar del Sur",
		["Wade into the pools to explore them"] = "Métete en las pozas para explorarlas",
		["Witchwing Slayers"] = "Destripadores Alabruja",
		["Witchwing harpies"] = "Arpías Alabruja",
		["Zhevra Runners graze on the same plains; finish the raptor heads as you go."] = "Los galopadores astacebra pastan en las mismas llanuras; termina las cabezas de raptor por el camino.",
		["Zhevra and raptors"] = "Astacebras y raptores",
		["{npc:3449}, on the tower platform: needs level 12"] = "{npc:3449}, en la plataforma de la torre: requiere nivel 12",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900} prepara {item:6636} con el alquitrán y la bolsa. Úsalo junto al brasero que tiene al lado para revelar a {npc:5893}, mátalo para conseguir {item:6655} y deja la ascua en el brasero.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}: {npc:2523}, tu {item:5176} y {item:263412}",
		["{quest:1492}, on the dock"] = "{quest:1492}, en el muelle",
} end)()
t.guides["forever/horde/skyborne/01-zephras-isle"] = (function() return {
		["Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies."] = "Aanders y los guardias caídos están justo al suroeste de la torre. Coge la Pluma de la suerte de Raani y el sello Cantosombrío de los cuerpos.",
		["Back at {quest:92529}: Stormcallers and {npc:251662} fill the village, the Supply Caches stand among the houses and {npc:251966} waits at its south-east end."] = "De vuelta en {quest:92529}: Clamatormentas Al'Aketh y {npc:251662} llenan el pueblo, los Cajones de provisiones están entre las casas y {npc:251966} espera en su extremo sureste.",
		["Bandit Highwaymen"] = "Bandidos salteadores",
		["Find {npc:258130}"] = "Encuentra a {npc:258130}",
		["Heal the injured druids in the Nightfang Den"] = "Cura a los druidas heridos de la Guarida Colmillo Nocturno",
		["High Order Apprentices"] = "Aprendices de la Orden Eminente",
		["Hippogryph nests"] = "Nidos de hipogrifo",
		["Horde airship"] = "Aeronave de la Horda",
		["Listen to {npc:252448}'s story"] = "Escucha la historia de {npc:252448}",
		["Listen to {npc:256083}"] = "Escucha a {npc:256083}",
		["Northern {zone:1412}"] = "Norte de {zone:1412}",
		["On the way north, back to {npc:255853} by the falls."] = "De camino al norte, vuelve con {npc:255853} junto a la cascada.",
		["Pesky Cirrusflies and {npc:250873} roam the grove just south-east of the village."] = "Moscas de cirro molestas y {npc:250873} deambulan por la arboleda justo al sureste del pueblo.",
		["Prideclaws and Galestriders"] = "Garramanadas y Zancavendavales",
		["Prideclaws and Galestriders share the meadows south of the village. Keep the {item:5469} for {npc:251905}; the eggs come later from the hippogryphs."] = "Garramanadas y Zancavendavales comparten los prados al sur del pueblo. Guarda la {item:5469} para {npc:251905}; los huevos vienen después, de los hipogrifos.",
		["Raw Windstones"] = "Piedras de viento en bruto",
		["Skyhoppers"] = "Saltanubes",
		["Skyhoppers hop about the fields just west of Valennia."] = "Los Saltanubes brincan por los campos justo al oeste de Valennia.",
		["Stormapples and flutterfly dust lie all over the orchard; Hungry Bandits raid it. Galestriders graze in the fields east of it. The broken construct floats at the orchard's north edge."] = "Hay Manzanas tempestuosas y Polvo de alabatiente por todo el huerto; los Bandidos hambrientos lo saquean. Los Zancavendavales pastan en los campos al este. El autómata roto flota en el borde norte del huerto.",
		["Talk to {npc:251902}"] = "Habla con {npc:251902}",
		["Talk to {npc:251968}"] = "Habla con {npc:251968}",
		["Talk to {npc:252383}"] = "Habla con {npc:252383}",
		["Talk to {npc:252800}"] = "Habla con {npc:252800}",
		["Talk to {npc:253576}"] = "Habla con {npc:253576}",
		["Talk to {npc:254089}"] = "Habla con {npc:254089}",
		["Tell {npc:252800} you're ready"] = "Dile a {npc:252800} que estás listo",
		["The Al'Aketh camp"] = "El campamento Al'Aketh",
		["The Al'Aketh cultists in the camp beyond {npc:252095} carry the signet."] = "Los cultistas Al'Aketh del campamento detrás de {npc:252095} llevan el sello.",
		["The Raw Windstones are blue crystals on the slopes around the village."] = "Las Piedras de viento en bruto son cristales azules en las laderas alrededor del pueblo.",
		["The Ursera den is west of the village. {npc:251115}, their matriarch, sits at its far end."] = "La guarida de los Ursera está al oeste del pueblo. {npc:251115}, su matriarca, está al fondo.",
		["The airship"] = "La aeronave",
		["The apprentices practise north-east of the village."] = "Los aprendices practican al noreste del pueblo.",
		["The bandit camps are north-east of the village; \"Badwind\" Bennic holds the top camp. Bandits carry the stolen windstones."] = "Los campamentos de bandidos están al noreste del pueblo; \"Malabrisa\" Bennic ocupa el campamento de arriba. Los bandidos llevan las piedras de viento robadas.",
		["The crawlers scuttle along the shore south-west of town."] = "Los reptadores corretean por la orilla al suroeste del pueblo.",
		["The highland bandits"] = "Los bandidos de las tierras altas",
		["The hippogryph nests are north-west of the tower, west of {quest:92529}; the Matriarch sits at the western end. {item:263493} lies on the ground around them, and the hippogryphs drop the Small Eggs."] = "Los nidos de hipogrifo están al noroeste de la torre, al oeste de {quest:92529}; la matriarca está en el extremo oeste. Hay {item:263493} en el suelo a su alrededor, y los hipogrifos sueltan los Huevos pequeños.",
		["The orchard"] = "El huerto",
		["The queen hovers at the south-east end of the grove, on your way back from the stones."] = "La Reina mosca de cirro revolotea en el extremo sureste de la arboleda, de camino de vuelta de las piedras.",
		["The standing stones"] = "Las piedras erguidas",
		["The turncoat"] = "El traidor",
		["The watchtower"] = "La atalaya",
		["The {object:148418}"] = "{object:148418}",
		["Wind Hollows and {object:616467}"] = "Huecos ventosos y {object:616467}",
		["Windsong Crawlers"] = "Reptadores Canzalvaje",
		["You leave the isle for good. {npc:259119} waits where the airship lands."] = "Dejas la isla para siempre. {npc:259119} espera donde aterriza la aeronave.",
		["search the dead cultist in the house"] = "registra al cultista muerto de la casa",
		["search the wardrobe"] = "registra el armario",
		["talk to {npc:251684}"] = "habla con {npc:251684}",
		["talk to {npc:251902}"] = "habla con {npc:251902}",
		["talk to {npc:251905}"] = "habla con {npc:251905}",
		["talk to {npc:251968}"] = "habla con {npc:251968}",
		["talk to {npc:252155}"] = "habla con {npc:252155}",
		["talk to {npc:252383}"] = "habla con {npc:252383}",
		["talk to {npc:252476}"] = "habla con {npc:252476}",
		["talk to {npc:257554}"] = "habla con {npc:257554}",
		["the bounty board"] = "el tablón de recompensas",
		["{item:265105} grows around {npc:257944}'s camp and Shriekings fly over it. The Al'Aketh camp east of her holds the {item:265141}."] = "El {item:265105} crece alrededor del campamento de {npc:257944} y los chilladores vuelan por encima. El campamento Al'Aketh al este de ella guarda la {item:265141}.",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, de {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, de {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, de {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, de {npc:3027}",
		["{npc:250926} prowl the slopes south-west of the village, on the way to {npc:252095}."] = "{npc:250926} merodean por las laderas al suroeste del pueblo, de camino a {npc:252095}.",
		["{npc:251361}'s errands"] = "Los recados de {npc:251361}",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}: una nota de tu instructor",
		["{npc:251361}: examine the {item:282418}"] = "{npc:251361}: examina el {item:282418}",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}: lee la {item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}: la {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}, el instructor de druidas, en la planta baja del árbol detrás de {npc:251361}",
		["{npc:251374} stands in the village."] = "{npc:251374} está en el pueblo.",
		["{npc:251374}, at the village centre"] = "{npc:251374}, en el centro del pueblo",
		["{npc:251374}: {npc:5873} and your {item:5175}"] = "{npc:251374}: {npc:5873} y tu {item:5175}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}, en la atalaya",
		["{npc:251964}, in the watchtower"] = "{npc:251964}, en la atalaya",
		["{npc:252382}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:252382}: {npc:2523}, tu {item:5176} y el {item:263412}",
		["{npc:252448} and {npc:256083}"] = "{npc:252448} y {npc:256083}",
		["{npc:253622}, {npc:258130} and {npc:258134} are in the cult camp east of {npc:257944}. {npc:254151} stands at its edge. Haalien also drops a {quest:94490}: read it to start the next quest. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:253622}, {npc:258130} y {npc:258134} están en el campamento del culto al este de {npc:257944}. {npc:254151} está en su borde. Haalien también suelta una {quest:94490}: léela para iniciar la siguiente misión. Para {quest:94489}, entra en la Guarida Colmillo Nocturno, cura a 7 druidas heridos y encuentra a {npc:258130}.",
		["{npc:254589} lurks south of the village, among the Prideclaws. {npc:254589} is elite: grouping up is advised."] = "{npc:254589} acecha al sur del pueblo, entre las Garramanadas. {npc:254589} es élite: se aconseja ir en grupo.",
		["{npc:255853} waits by the falls just north of the watchtower."] = "{npc:255853} espera junto a la cascada, justo al norte de la atalaya.",
		["{npc:257196} holds the {item:263993} on the west side of the shrine."] = "{npc:257196} tiene el {item:263993} en el lado oeste del santuario.",
		["{npc:257944} again"] = "{npc:257944} otra vez",
		["{npc:257944}, last time"] = "{npc:257944}, última vez",
		["{npc:258443} roams the slopes just south of the turncoat's house."] = "{npc:258443} deambula por las laderas justo al sur de la casa del traidor.",
		["{npc:259118}, by the landing: for {npc:3033} in {zone:1456}"] = "{npc:259118}, junto al aterrizaje: para {npc:3033} en {zone:1456}",
		["{npc:259119}: keep it, Thrall in {zone:1454} comes two guides later"] = "{npc:259119}: guárdala, Thrall en {zone:1454} llega dos guías después",
		["{npc:263664}'s campfire"] = "La hoguera de {npc:263664}",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} quiere incienso tauren: compra sus cuatro partes a {npc:3014} la herbolaria, {npc:3012} la proveedora de encantamiento, {npc:3005} el proveedor de peletería y {npc:3027} el proveedor de cocina; luego combínalas en {item:278078}.",
		["{npc:3615}, the wind rider master"] = "{npc:3615}, el maestro de jinetes del viento",
		["{quest:92529} lies south of Shen'dar. {npc:257065} meets you at its edge; search the wardrobe in the house behind him."] = "{quest:92529} está al sur de Shen'dar. {npc:257065} te recibe en su linde; registra el armario de la casa detrás de él.",
} end)()
t.guides["forever/horde/tauren/01-mulgore"] = (function() return {
		["Back to Bloodhoof"] = "Vuelve al Poblado Pezuña de Sangre",
		["Back to {npc:5888} in the camp. The {npc:5891} waits on the mesa east of the camp: drink the {item:6635} there to see it, then take the {item:6656} back to the Seer."] = "Vuelve con {npc:5888} en el campamento. {npc:5891} espera en la meseta al este del campamento: bebe {item:6635} allí para verla y lleva {item:6656} al profeta.",
		["Back west to the camp."] = "Vuelve al oeste, al campamento.",
		["Battleboars graze north of the shrine; the Bristleback quilboar hold the ravine to the north-east. {npc:8554} stands at its eastern end, and the {object:3076} lies on the ground in the camp."] = "Los jabaguerreros pastan al norte del santuario; los jabaespines Lomopelo ocupan el barranco del noreste. {npc:8554} está en su extremo este, y {object:3076} está en el suelo del campamento.",
		["Finish the wolf heart, cougar femur, plainstrider scale and swoop gizzard on the plains around the village."] = "Termina el corazón de lobo, el fémur de puma, la escama de zancudo y la molleja de aguilón en las llanuras alrededor del poblado.",
		["Follow the path south out of camp to the Seer's tent at the foot of the hills."] = "Sigue el sendero hacia el sur fuera del campamento hasta la tienda del profeta, al pie de las colinas.",
		["Galak centaurs"] = "Centauros Galak",
		["Plainstriders roam the grass all around the camp."] = "Los zancudos de llanura recorren la hierba alrededor del campamento.",
		["Prairie Wolf Alphas"] = "Lobos alfa de pradera",
		["Prairie Wolf Alphas roam among the wolves on the plains around {npc:275789} and the Galak camp to the east."] = "Los Lobos alfa de pradera rondan entre los lobos de las llanuras alrededor de {npc:275789} y del campamento Galak al este.",
		["Prairie Wolves and Adult Plainstriders roam the plains around the village."] = "Los lobos de pradera y los zancudos de llanura adultos recorren las llanuras alrededor del poblado.",
		["Ride a lift up to the mesas. {npc:2995} keeps the wind riders on the central rise; {npc:3057} stands in the great tent there."] = "Sube en un elevador a las mesetas. {npc:2995} cuida de los jinetes del viento en el alto central; {npc:3057} está en la gran tienda de allí.",
		["Speak with {npc:3067}"] = "Habla con {npc:3067}",
		["Swoops glide over the plains all around Bloodhoof."] = "Los aguilones planean sobre las llanuras alrededor del Poblado Pezuña de Sangre.",
		["Tame it with the {item:15908}"] = "Domestícalo con {item:15908}",
		["The Galak centaurs camp on the plains east of the well; {npc:275767} leads them."] = "Los centauros Galak acampan en las llanuras al este del pozo; {npc:275767} los dirige.",
		["The goblins work the mine in the hills north-east of the well. {quest:765} stands in the back of the mine; his {item:281031} start {quest:98424}, and the other pages lie inside the mine."] = "Los goblins explotan la mina de las colinas al noreste del pozo. {quest:765} está al fondo de la mina; sus {item:281031} inician {quest:98424}, y las demás páginas están dentro de la mina.",
		["The incense burns out in ten minutes: run straight east along the southern hills to the {object:660739}."] = "El incienso se consume en diez minutos: corre directo hacia el este por las colinas del sur hasta {object:660739}.",
		["The shrine of An'she and Mu'sha"] = "El santuario de An'she y Mu'sha",
		["The stone stands in the pass out of {zone:1412}, on your way east. Use the {item:15710} there and defeat Lunaclaw."] = "La piedra está en el paso que sale de {zone:1412}, de camino al este. Usa {item:15710} allí y derrota a Garraluna.",
		["The well lies north of the village. Well Stones sit around the well, {object:2912} lies under the trees nearby. Kill wolves, cougars, plainstriders and swoops on the way for {quest:766} and {quest:761}."] = "El pozo está al norte del poblado. Las piedras de pozo están alrededor del pozo, y {object:2912}, bajo los árboles cercanos. Mata lobos, pumas, zancudos de llanura y aguilones por el camino para {quest:766} y {quest:761}.",
		["The well lies south-east of the village."] = "El pozo está al sureste del poblado.",
		["The wrecked caravan lies north-west of the centaurs, east of the road to {zone:1456}."] = "La caravana destrozada está al noroeste de los centauros, al este del camino a {zone:1456}.",
		["The {object:177525}"] = "{object:177525}",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, de {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, de {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, de {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, de {npc:3027}",
		["{item:4703}, at the digsite forge"] = "{item:4703}, en la forja de la excavación",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} quiere incienso tauren: compra sus cuatro partes a {npc:3014}, la herbolaria; a {npc:3012}, proveedora de encantamiento; a {npc:3005}, proveedora de peletería, y a {npc:3027}, proveedor de cocina; luego combínalas en {item:278078}.",
		["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "{npc:277182} está en el borde norte del poblado. Kyle quiere {item:287505} de zancudos de llanura.",
		["{npc:277182}, at the north end of the village"] = "{npc:277182}, en el extremo norte del poblado",
		["{npc:2948}, for Hamuul in {zone:1456}"] = "{npc:2948}, para Hamuul en {zone:1456}",
		["{npc:2991} sits by the tent on the camp's eastern edge; the {object:2907} stands next to her."] = "{npc:2991} está sentada junto a la tienda del borde este del campamento; {object:2907} está a su lado.",
		["{npc:2993}, for {npc:3057} in {zone:1456}"] = "{npc:2993}, para {npc:3057} en {zone:1456}",
		["{npc:3059}, the warrior trainer"] = "{npc:3059}, el instructor de guerreros",
		["{npc:3060}, the druid trainer beside him"] = "{npc:3060}, el instructor de druidas, a su lado",
		["{npc:3061}, the hunter trainer"] = "{npc:3061}, la instructora de cazadores",
		["{npc:3062}, the shaman trainer in camp"] = "{npc:3062}, la instructora de chamanes del campamento",
		["{npc:3063}'s quest: beat three Novice Warriors (or players in duels) next to him."] = "Misión de {npc:3063}: vence a tres guerreros novicios (o a jugadores en duelos) a su lado.",
		["{npc:3209}, next to {npc:2980}"] = "{npc:3209}, junto a {npc:2980}",
		["{npc:5888}: {npc:5873} and your {item:5175}"] = "{npc:5888}: {npc:5873} y tu {item:5175}",
		["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, hunt the cougars from there south and east, then come back up to {npc:2980}."] = "{npc:6775} está en el extremo oeste del campamento, en la esquina noroeste de las colinas donde rondan los pumas monteses: acepta su misión, caza los pumas desde allí hacia el sur y el este y vuelve con {npc:2980}.",
		["{quest:96130} and {quest:756}"] = "{quest:96130} y {quest:756}",
		["{quest:96130}, a lone wolf, prowls the plains west of the village. Prairie Stalkers and Flatland Cougars roam the plains north and west of it."] = "{quest:96130}, un lobo solitario, ronda las llanuras al oeste del poblado. Los acechadores de pradera y los pumas de las estepas recorren las llanuras al norte y al oeste.",
} end)()
t.guides["forever/horde/undead/01-tirisfal-glades"] = (function() return {
		["Ask {npc:10666} for his report"] = "Pide su informe a {npc:10666}",
