		["{npc:2128}: {npc:4568} in the {zone:1458} takes it"] = "{npc:2128}: lo recoge {npc:4568}, en {zone:1458}",
		["{npc:2132}, beside Johaan"] = "{npc:2132}, junto a Johann",
