t.guides["forever/reputation/cenarion-circle"] = (function() return {
		["Abyssal Crests, Abyssal Signets and Abyssal Scepters are repeatable at {npc:15306} once their opening quests are done."] = "Emblemas Abisales, Sellos Abisales y Cetros Abisales se repiten con {npc:15306} cuando completas sus misiones iniciales.",
		["Cenarion Circle Reputation"] = "Reputación: Círculo Cenarion",
		["Encrypted Twilight Texts repeats: {npc:15306} takes more texts again and again. The cultist camps are the place to farm them."] = "Textos Crepusculares encriptados se repite: {npc:15306} acepta más textos una y otra vez. Los campamentos de cultores son el sitio para conseguirlos.",
		["Encrypted Twilight Texts to Friendly"] = "Textos crepusculares codificados hasta Amistoso",
		["Keep farming the Twilight camps. Wearing the Twilight Trappings (the Twilight cultist set plus a Medallion of Station, from {npc:15282}'s Medallion of Station quest) lets you summon Abyssal Templars at the Wind Stones; their Abyssal Crests go to {npc:15306}."] = "Sigue limpiando los campamentos Crepusculares. Con el atuendo de fiel del Crepúsculo puesto (el conjunto de fiel del Crepúsculo más un Medallón de estatus, de la misión Medallón de estatus de {npc:15282}) puedes invocar templarios abisales en las piedras de viento; sus emblemas abisales van para {npc:15306}.",
		["Twilight's Hammer cultists hold the camps in western {zone:1451}. {quest:8320} and Stonecallers mix here; any cultist can drop an {item:20404}. Every cultist kill also counts toward the {faction:609}. The Geolords count for {quest:8320} only if you are 60 and took it."] = "Los cultores del Martillo Crepuscular ocupan los campamentos del oeste de {zone:1451}. Aquí se mezclan {quest:8320} y Clamapiedras Crepusculares; cualquier cultor puede soltar un {item:20404}. Cada cultor que matas también cuenta para el {faction:609}. Los Geoseñores solo cuentan para {quest:8320} si eres de nivel 60 y la aceptaste.",
		["{faction:609} to Exalted"] = "{faction:609} hasta Exaltado",
		["{faction:609} to Honored"] = "{faction:609} hasta Honorable",
		["{faction:609} to Revered"] = "{faction:609} hasta Venerado",
		["{npc:15306}: Encrypted Twilight Texts"] = "{npc:15306}: Textos Crepusculares encriptados",
		["{quest:8320} needs level 60"] = "{quest:8320} requiere nivel 60",
} end)()
t.guides["forever/reputation/darkspear-trolls"] = (function() return {
		["Dark Adepts and Shadowmages (level 58-60) drop it here; every Scourge kill here also counts toward the {object:92525} (see that guide). The Auction House works too."] = "Lo sueltan los Adeptos oscuros y Magos oscuros de aquí (nivel 58-60); cada miembro de la Plaga que mates aquí también cuenta para la reputación con {object:92525} (consulta esa guía). También puedes comprarlo en la casa de subastas.",
		["Darkspear Trolls Reputation"] = "Reputación: Trols de Lanza Negra",
		["Dunemaul ogres (level 45-48) drop it here. The Auction House works too."] = "Lo sueltan los ogros Machacaduna de aquí (nivel 45-48). También puedes comprarlo en la casa de subastas.",
		["Keep handing in {quest:7837} until {faction:530} is Exalted. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "Sigue entregando {quest:7837} hasta llegar a Exaltado con {faction:530}. {item:14047}: Adeptos oscuros y Magos oscuros (nivel 58-60) en {zone:1423}, o la casa de subastas.",
		["Keep handing in {quest:7837}, 20 {item:14047} at a time. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "Sigue entregando {quest:7837}, 20 de {item:14047} cada vez. {item:14047}: Adeptos oscuros y Magos oscuros (nivel 58-60) en {zone:1423}, o la casa de subastas.",
		["Kolkar centaur (level 30-33) drop it here. The Auction House works too."] = "Lo sueltan los centauros Kolkar de aquí (nivel 30-33). También puedes comprarlo en la casa de subastas.",
		["{npc:14727} takes cloth for {faction:530} in the {object:172961}, {zone:1454}. The first donations of Wool, Silk, Mageweave and {item:14047} (60 cloth each) are done once and give the most reputation per cloth; after them, {quest:7837} repeats until Exalted. Exalted with another race's city lets you buy that race's mounts. Forever's Legacy Diplomat perk increases reputation gains."] = "{npc:14727} recoge paño para {faction:530} en el {object:172961}, {zone:1454}. Las primeras donaciones de lana, seda, paño mágico y {item:14047} (60 paños cada una) se hacen una sola vez y dan la mayor reputación por paño; después, {quest:7837} se repite hasta Exaltado. Ser Exaltado con la ciudad de otra raza te permite comprar sus monturas. La ventaja de Legado Diplomático de Forever aumenta la reputación que ganas.",
		["{npc:14727}: {item:14047} delivered"] = "{npc:14727}: {item:14047} entregado",
		["{quest:7837} takes 20 {item:14047} per turn-in and repeats as often as you like. Bring {item:14047} in multiples of 20 and hand them all in at once, one turn-in after another. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "{quest:7837} pide 20 de {item:14047} por entrega y se repite tantas veces como quieras. Lleva {item:14047} en múltiplos de 20 y entrégalo todo de una vez, una entrega tras otra. {item:14047}: Adeptos oscuros y Magos oscuros (nivel 58-60) en {zone:1423}, o la casa de subastas.",
		["{quest:7837} to Exalted"] = "{quest:7837} hasta Exaltado",
		["{quest:7837} to Honored"] = "{quest:7837} hasta Honorable",
