		["{npc:14728} takes cloth for {faction:81} in {faction:81}. The first donations of Wool, Silk, Mageweave and {item:14047} (60 cloth each) are done once and give the most reputation per cloth; after them, {quest:7825} repeats until Exalted. Exalted with another race's city lets you buy that race's mounts. Forever's Legacy Diplomat perk increases reputation gains."] = "{npc:14728} acepta tela para {faction:81} en {faction:81}. Las primeras donaciones de Paño de lana, Paño de seda, Tela de paño mágico y {item:14047} (60 telas cada una) se hacen una sola vez y dan la mayor reputación por tela; después, {quest:7825} se repite hasta Exaltado. Ser Exaltado con la ciudad de otra raza te permite comprar las monturas de esa raza. La ventaja de Legado Diplomático de Forever aumenta la reputación obtenida.",
		["{npc:14728}: {item:14047} delivered"] = "{npc:14728}: {item:14047} entregado",
		["{quest:7825} takes 20 {item:14047} per turn-in and repeats as often as you like. Bring {item:14047} in multiples of 20 and hand them all in at once, one turn-in after another. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "{quest:7825} pide 20 {item:14047} por entrega y se repite tantas veces como quieras. Lleva {item:14047} en múltiplos de 20 y entrégalo todo de una vez, una entrega tras otra. {item:14047}: Adeptos oscuros y magos oscuros (nivel 58-60) en {zone:1423}, o la casa de subastas.",
		["{quest:7825} to Exalted"] = "{quest:7825} hasta Exaltado",
		["{quest:7825} to Honored"] = "{quest:7825} hasta Honorable",
		["{quest:7825} to Revered"] = "{quest:7825} hasta Reverenciado",
} end)()
t.guides["forever/reputation/timbermaw-hold"] = (function() return {
		["Alternate Deadwood feathers ({npc:15395}) and Winterfall beads ({npc:11556}), whichever camp is less crowded."] = "Alterna plumas Muertobosque ({npc:15395}) y cuentas Nevada ({npc:11556}), según qué campamento esté menos concurrido.",
		["Back to {npc:11554}"] = "Vuelve con {npc:11554}",
		["Back to {npc:11556}"] = "Vuelve con {npc:11556}",
		["Back to {npc:15395}"] = "Vuelve con {npc:15395}",
		["Deadwood furbolgs (level 48-50) camp at the southern end of {zone:1448}. Keep every {item:21377} they drop: {npc:11554} and {npc:15395} take them later."] = "Los fúrbolgs Muertobosque (nivel 48-50) acampan en el extremo sur de {zone:1448}. Guarda cada {item:21377} que suelten: {npc:11554} y {npc:15395} las aceptan más tarde.",
		["Feathers and beads to Friendly"] = "Plumas y cuentas hasta Amistoso",
		["Feathers to Honored"] = "Plumas hasta Honorable",
		["Go through {faction:576} to its {zone:1452} exit; {npc:11556} stands just outside. The quests and kills so far usually reach Unfriendly, and then the Timbermaw let you pass. If they still show red, kill more Deadwood by the tunnel first."] = "Atraviesa {faction:576} hasta su salida a {zone:1452}; {npc:11556} está justo fuera. Las misiones y muertes hasta ahora suelen bastar para llegar a Adverso, y entonces los Fauces de Madera te dejan pasar. Si siguen en rojo, mata antes más Muertobosque junto al túnel.",
		["Keep turning in feathers and beads until Exalted."] = "Sigue entregando plumas y cuentas hasta Exaltado.",
		["The northern Deadwood (level 53-55) hold the camps just south of the tunnel. Keep their feathers too."] = "Los Muertobosque del norte (nivel 53-55) ocupan los campamentos justo al sur del túnel. Guarda también sus plumas.",
		["The northern Deadwood camps by the tunnel are the densest feather spot (35% drop chance there). Hand feathers to {npc:15395} at the tunnel, or to {npc:11554} in the south."] = "Los campamentos Muertobosque del norte, junto al túnel, son el mejor sitio para las plumas (allí caen un 35% de las veces). Entrega las plumas a {npc:15395} en el túnel, o a {npc:11554} en el sur.",
		["Timbermaw Hold Reputation"] = "Reputación: Bastión de los Fauces de Madera",
		["{faction:576} starts out Hostile, and its furbolgs in the tunnels attack until you reach Unfriendly. Every Deadwood and Winterfall furbolg you kill raises it, so the quests below pay twice. Forever's Legacy Diplomat perk increases reputation gains."] = "{faction:576} empieza en Hostil, y sus fúrbolgs de los túneles te atacan hasta que llegas a Adverso. Cada fúrbolg Muertobosque o Nevada que matas la sube, así que las misiones de abajo dan reputación por partida doble. La ventaja de Legado Diplomático de Forever aumenta la reputación que ganas.",
		["{faction:576} to Exalted"] = "{faction:576} hasta Exaltado",
		["{faction:576} to Revered"] = "{faction:576} hasta Venerado",
		["{npc:11556}: Beads for {npc:11556}"] = "{npc:11556}: Cuentas para {npc:11556}",
		["{npc:15395} waits in northern {zone:1448} at the tunnel into {faction:576}."] = "{npc:15395} espera en el norte de {zone:1448}, en el túnel que lleva a {faction:576}.",
		["{npc:15395}: Feathers for {npc:15395}"] = "{npc:15395}: Plumas para {npc:15395}",
} end)()
